:"7961a70c156c8b124ab4c89dcc4662ef","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_economic_outbox.guard_guardrail_reservation_after_denial()","digest":"8defeb190527985f2928c856cfa11f29","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_economic_outbox.guard_v2_reservation_mutation()","digest":"ea9c363cfbb832a9f414ada3cee1a6cb","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_economic_outbox.lock_request_economic_enrollment()","digest":"55e9e7b94e2099548dfbec23425c9fc0","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_economic_outbox.mark_shared_key_buyer_log_tx()","digest":"371e7930db542a724cf0385fbf6a1183","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_economic_outbox.require_event_for_buyer_log()","digest":"dedde60c7696048bdedb9c2459aa83a7","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_gateway.enforce_request_log_workspace()","digest":"81f5dfeb50e2a156e054a34486531840","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, cinatoken_gateway, pg_temp"],"securityDefiner":false,"executeAcl":[{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"EXECUTE"}]},{"signature":"cinatoken_gateway.reject_complete_text_admission_mutation_v361()","digest":"dd5b0152e3a87b2a5a771c00dd7376b1","returnType":"trigger","volatility":"v","config":["search_path=pg_catalog, pg_temp"],"securityDefiner":true,"executeAcl":[]},{"signature":"cinatoken_gateway.seed_gu