  role_contract:=$roles${"cinatoken_gateway_complete_text_send_holder":["cinatoken_gateway.claim_complete_text_send_custody_v365(uuid,uuid)","cinatoken_gateway.record_complete_text_send_start_v365(uuid,uuid,bigint,text)","cinatoken_gateway.append_complete_text_holder_fact_v366(uuid,uuid,bigint,uuid,text,jsonb,text)","cinatoken_gateway.append_complete_text_response_observation_v392(uuid,uuid,uuid,bigint,uuid,jsonb)"],"cinatoken_gateway_complete_text_response_observer":["cinatoken_gateway.read_complete_text_response_observation_v392(uuid)"],"cinatoken_gateway_complete_text_no_fetch_resolver":["cinatoken_gateway.resolve_complete_text_no_fetch_v370(uuid,uuid)"],"cinatoken_gateway_complete_text_platform_closer":["cinatoken_gateway.close_complete_text_no_fetch_v388(uuid,uuid,uuid)"],"cinatoken_gateway_complete_text_hold_renewer":["cinatoken_gateway.renew_complete_text_holds_v367(uuid,uuid,uuid,bigint)"],"cinatoken_gateway_complete_text_recovery_worker":["cinatoken_gateway.scan_complete_text_no_fetch_recovery_v389(integer)","cinatoken_gateway.claim_complete_text_no_fetch_recovery_v389(integer)","cinatoken_gateway.fail_complete_text_no_fetch_recovery_v389(uuid,uuid,text)"],"cinatoken_gateway_complete_text_recovery_observer":["cinatoken_gateway.observe_complete_text_no_fetch_recovery_v389(uuid,uuid)","cinatoken_gateway.finish_complete_text_no_fetch_recovery_v389(uuid,uuid)"],"cinatoken_gateway_complete_text_recovery_operator":["cinatoken_gateway.recover_complete_text_no_fetch_recovery_v389(uuid,text)"],"cinatoken_gateway_complete_text_attempt_granter":["cinatoken_gateway.grant_complete_flat_text_attempt_v362(uuid,jsonb)"],"cinatoken_gateway_complete_text_provider_bill":["cinatoken_gateway.append_complete_text_provider_bill_v366(uuid,uuid,jsonb,text)"]}$roles$::jsonb;
  financial_acl:=$acl$[{"name":"users","acl":[{"role":"cinatoken_gateway_buyer_settlement","grantable":false,"privilege":"SELECT"},{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"SELECT"}],"columnAcl":[]},{"name":"api_key_request_logs","acl":[{"role":"cinatoken_gateway_buyer_settlement","grantable":false,"privilege":"INSERT"},{"role":"cinatoken_gateway_buyer_settlement","grantable":false,"privilege":"SELECT"},{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"INSERT"},{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"SELECT"}],"columnAcl":[]},{"name":"guardrail_budget_windows","acl":[{"role":"cinatoken_gateway_buyer_settlement","grantable":false,"privilege":"SELECT"},{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"SELECT"}],"columnAcl":[]},{"name":"guardrail_budget_reservations","acl":[{"role":"cinatoken_gateway_buyer_settlement","grantable":false,"privilege":"SELECT"},{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"SELECT"}],"columnAcl":[]},{"name":"user_budget_reservations","acl":[{"role":"cinatoken_gateway_buyer_settlement","grantable":false,"privilege":"SELECT"},{"role":"cinatoken_gateway_runtime","grantable":false,"privilege":"SELECT"}],"columnAcl":[]}]$acl$::jsonb;
  SELECT array_agg(DISTINCT to_regclass(x->>'table')) INTO relation_oids FROM jsonb_array_elements(expected_triggers) x;
  relation_oids:=relation_oids||ARRAY['cinatoken_gateway.users'::regclass::oid];
  IF EXISTS (SELECT 1 FROM unnest(relation_oids) x WHERE x IS NULL)
    OR EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=ANY(relation_oids)
      AND (c.relowner<>owner_oid OR n.nspowner<>owner_oid OR c.relkind<>'r' OR c.relrowsecurity OR c.relforcerowsecurity
        OR (c.relname NOT IN ('api_key_request_logs','user_budget_reservations','guardrail_budget_reservations','users','guardrail_budget_windows') AND EXISTS(SELECT 1 FROM aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>owner_oid))))
    OR EXISTS (SELECT 1 FROM pg_attribute c,LATERAL aclexplode(c.attacl) a WHERE c.attrelid=ANY(relation_oids) AND a.grantee<>owner_oid AND c.attrelid NOT IN ('cinatoken_gateway.api_key_request_logs'::regclass,'cinatoken_gateway.user_budget_reservations'::regclass,'cinatoken_gateway.guardrail_budget_reservations'::regclass,'cinatoken_gateway.users'::regclass,'cinatoken_gateway.guardrail_budget_windows'::regclass))
    OR EXISTS (SELECT 1 FROM pg_rewrite WHERE ev_class=ANY(relation_oids))
  THEN RAISE EXCEPTION 'coinstall v397 table authority differs' USING ERRCODE='P0001'; END IF;
  FOR dependency IN SELECT * FROM jsonb_array_elements(financial_acl) LOOP
    SELECT COALESCE(jsonb_agg(jsonb_build_object('role',r.rolname,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY r.rolname,a.privilege_type) FILTER(WHERE a.grantee<>c.relowner),'[]'::jsonb) INTO actual_acl
      FROM pg_class c CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a LEFT JOIN pg_roles r ON r.oid=a.grantee
      WHERE c.oid=to_regclass('cinatoken_gateway.'||(dependency->>'name'));
    IF actual_acl IS DISTINCT FROM dependency->'acl' OR EXISTS(SELECT 1 FROM pg_attribute c,LATERAL aclexplode(c.attacl) a
      WHERE c.attrelid=to_regclass('cinatoken_gateway.'||(dependency->>'name')) AND a.grantee<>owner_oid)
    THEN RAISE EXCEPTION 'coinstall v397 financial table ACL differs: %',dependency->>'name' USING ERRCODE='P0001'; END IF;
  END LOOP;
  FOR dependency IN SELECT * FROM jsonb_array_elements(function_pins) LOOP
    SELECT * INTO proc_row FROM pg_proc WHERE oid=to_regprocedure(dependency->>'signature');
    IF NOT FOUND OR proc_row.proowner<>owner_oid OR proc_row.prosecdef IS DISTINCT FROM COALESCE((dependency->>'securityDefiner')::boolean,true) OR proc_row.prokind<>'f'
      OR proc_row.proretset OR proc_row.proisstrict OR proc_row.proleakproof OR proc_row.proparallel<>'u'
      OR proc_row.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql')
      OR proc_row.prorettype<>to_regtype(dependency->>'returnType') OR proc_row.provolatile::text<>dependency->>'volatility'
      OR COALESCE(to_jsonb(proc_row.proconfig),'null'::jsonb) IS DISTINCT FROM dependency->'config'
      OR md5(replace(proc_row.prosrc,E'\r\n',E'\n')) IS DISTINCT FROM dependency->>'digest'
    THEN RAISE EXCEPTION 'coinstall v397 function dependency differs: %',dependency->>'signature' USING ERRCODE='P0001'; END IF;
    SELECT array_agg(r.oid) INTO permitted_grantees FROM pg_roles r
      WHERE r.rolname IN (SELECT k FROM jsonb_each(role_contract) item(k,v)
        WHERE v ? (dependency->>'signature'));
    SELECT COALESCE(jsonb_agg(jsonb_build_object('role',COALESCE(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY COALESCE(r.rolname,'PUBLIC'),a.privilege_type) FILTER(WHERE a.grantee<>owner_oid),'[]'::jsonb) INTO actual_acl
      FROM aclexplode(COALESCE(proc_row.proacl,acldefault('f',owner_oid))) a LEFT JOIN pg_roles r ON r.oid=a.grantee;
    IF (dependency ? 'executeAcl' AND actual_acl IS DISTINCT FROM dependency->'executeAcl') OR (NOT dependency ? 'executeAcl' AND EXISTS(SELECT 1 FROM aclexplode(COALESCE(proc_row.proacl,acldefault('f',owner_oid))) a
      WHERE a.grantee<>owner_oid AND (a.privilege_type<>'EXECUTE' OR a.is_grantable
        OR NOT a.grantee=ANY(COALESCE(permitted_grantees,ARRAY[]::oid[])))))
    THEN RAISE EXCEPTION 'coinstall v397 function ACL differs: %',dependency->>'signature' USING ERRCODE='P0001'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_trigger WHERE tgrelid=ANY(relation_oids) AND NOT tgisinternal)<>jsonb_array_length(expected_triggers)
  THEN RAISE EXCEPTION 'coinstall v397 trigger inventory differs' USING ERRCODE='P0001'; END IF;
  FOR dependency IN SELECT * FROM jsonb_array_elements(expected_triggers) LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass(dependency->>'table')
      AND t.tgname=dependency->>'name' AND t.tgfoid=to_regprocedure(dependency->>'function')
      AND t.tgtype=(dependency->>'type')::integer AND t.tgenabled='O' AND NOT t.tgisinternal
      AND t.tgqual IS NULL AND t.tgattr::text='' AND t.tgnargs=0 AND t.tgoldtable IS NULL AND t.tgnewtable IS NULL
      AND t.tgdeferrable=(dependency->>'deferrable')::boolean AND t.tginitdeferred=(dependency->>'initiallyDeferred')::boolean)
    THEN RAISE EXCEPTION 'coinstall v397 trigger shape differs: %',dependency->>'name' USING ERRCODE='P0001'; END IF;
  END LOOP;
  FOR role_name IN SELECT jsonb_object_keys(role_contract) LOOP
    SELECT * INTO actor FROM pg_roles WHERE rolname=role_name;
    SELECT array_agg(to_regprocedure(x)) INTO allowed FROM jsonb_array_elements_text(role_contract->role_name) x;
    IF actor.oid IS NULL OR NOT actor.rolcanlogin OR actor.rolinherit OR actor.rolsuper OR actor.rolcreaterole
      OR actor.rolcreatedb OR actor.rolreplication OR actor.rolbypassrls
      OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=actor.oid OR roleid=actor.oid)
      OR EXISTS(SELECT 1 FROM unnest(allowed) x WHERE x IS NULL OR NOT has_function_privilege(actor.oid,x,'EXECUTE'))
      OR EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname LIKE 'cinatoken_%'
        AND (has_schema_privilege(actor.oid,n.oid,'CREATE') OR (n.nspname<>'cinatoken_gateway' AND has_schema_privilege(actor.oid,n.oid,'USAGE'))))
      OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname LIKE 'cinatoken_%'
        AND CASE WHEN c.relkind IN ('r','p','v','m','f') THEN has_table_privilege(actor.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
          OR has_any_column_privilege(actor.oid,c.oid,'SELECT,INSERT,UPDATE') WHEN c.relkind='S' THEN has_sequence_privilege(actor.oid,c.oid,'SELECT,USAGE,UPDATE') ELSE false END)
      OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname LIKE 'cinatoken_%' OR p.proowner=owner_oid)
        AND has_function_privilege(actor.oid,p.oid,'EXECUTE') AND (NOT p.oid=ANY(allowed) OR has_function_privilege(actor.oid,p.oid,'EXECUTE WITH GRANT OPTION')))
    THEN RAISE EXCEPTION 'coinstall v397 role authority differs: %',role_name USING ERRCODE='P0001'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM pg_default_acl d,LATERAL aclexplode(d.defaclacl) a
    WHERE d.defaclrole=owner_oid AND d.defaclobjtype='f' AND d.defaclnamespace IN (0,'cinatoken_response_observation'::regnamespace)
      AND a.grantee<>owner_oid AND NOT(a.grantee=0 AND a.privilege_type='EXECUTE' AND NOT a.is_grantable))
    OR EXISTS(SELECT 1 FROM cinatoken_response_observation.observations_v392 o
      WHERE EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_no_fetch_resolutions_v370 r WHERE r.request_id=o.request_id)
        OR EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_platform_terminals_v388 t WHERE t.request_id=o.request_id))
  THEN RAISE EXCEPTION 'coinstall v397 default ACL or preexisting overlap differs' USING ERRCODE='P0001'; END IF;
END;
$preflight$;

CREATE FUNCTION cinatoken_response_observation.reject_no_fetch_overlap_v397()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path TO pg_catalog,pg_temp SET lock_timeout TO '2s' SET statement_timeout TO '15s' AS $fence$
DECLARE request_key text;
BEGIN
  SELECT request_id INTO request_key FROM cinatoken_gateway.complete_text_attempt_grants_v362 WHERE grant_id=NEW.grant_id;
  IF request_key IS NULL OR request_key IS DISTINCT FROM NEW.request_id THEN
    RAISE EXCEPTION 'coinstall response/no-fetch grant identity differs' USING ERRCODE='23514',CONSTRAINT='response_no_fetch_overlap_v397';
  END IF;
  PERFORM pg_advisory_xact_lock(348,hashtext(request_key));
  IF NOT EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_attempt_grants_v362 WHERE grant_id=NEW.grant_id AND request_id=request_key)
  THEN RAISE EXCEPTION 'coinstall grant changed' USING ERRCODE='23514',CONSTRAINT='response_no_fetch_overlap_v397'; END IF;
  IF TG_TABLE_SCHEMA='cinatoken_response_observation' AND TG_TABLE_NAME='observations_v392' THEN
    IF SESSION_USER<>'cinatoken_gateway_complete_text_send_holder'
      OR EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_no_fetch_resolutions_v370 WHERE request_id=request_key)
      OR EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_platform_terminals_v388 WHERE request_id=request_key)
    THEN RAISE EXCEPTION 'complete response cannot coexist with no-fetch' USING ERRCODE='23514',CONSTRAINT='response_no_fetch_overlap_v397'; END IF;
  ELSIF TG_TABLE_SCHEMA='cinatoken_gateway' AND TG_TABLE_NAME IN ('complete_text_no_fetch_resolutions_v370','complete_text_platform_terminals_v388') THEN
    IF (TG_TABLE_NAME='complete_text_no_fetch_resolutions_v370' AND SESSION_USER<>'cinatoken_gateway_complete_text_no_fetch_resolver')
      OR (TG_TABLE_NAME='complete_text_platform_terminals_v388' AND SESSION_USER<>'cinatoken_gateway_complete_text_platform_closer')
      OR EXISTS(SELECT 1 FROM cinatoken_response_observation.observations_v392 WHERE request_id=request_key)
      OR EXISTS(SELECT 1 FROM cinatoken_gateway.complete_text_send_starts_v365 WHERE request_id=request_key)
    THEN RAISE EXCEPTION 'no-fetch cannot coexist with a send start or response' USING ERRCODE='23514',CONSTRAINT='response_no_fetch_overlap_v397'; END IF;
  ELSE RAISE EXCEPTION 'invalid coinstall fence target' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END;
$fence$;
CREATE TRIGGER response_observation_no_fetch_fence_v397 BEFORE INSERT ON cinatoken_response_observation.observations_v392
  FOR EACH ROW EXECUTE FUNCTION cinatoken_response_observation.reject_no_fetch_overlap_v397();
CREATE TRIGGER no_fetch_response_fence_v397 BEFORE INSERT ON cinatoken_gateway.complete_text_no_fetch_resolutions_v370
  FOR EACH ROW EXECUTE FUNCTION cinatoken_response_observation.reject_no_fetch_overlap_v397();
CREATE TRIGGER platform_terminal_response_fence_v397 BEFORE INSERT ON cinatoken_gateway.complete_text_platform_terminals_v388
  FOR EACH ROW EXECUTE FUNCTION cinatoken_response_observation.reject_no_fetch_overlap_v397();
REVOKE ALL ON FUNCTION cinatoken_response_observation.reject_no_fetch_overlap_v397() FROM PUBLIC,cinatoken_gateway_runtime;
DO $postflight$
DECLARE owner_oid oid;
BEGIN
  SELECT oid INTO owner_oid FROM pg_roles WHERE rolname='cinatoken_gateway_migrator';
  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid='cinatoken_response_observation.reject_no_fetch_overlap_v397()'::regprocedure
      AND p.proowner=owner_oid AND p.prosecdef AND p.prokind='f' AND p.prorettype='trigger'::regtype
      AND p.proconfig=ARRAY['search_path=pg_catalog, pg_temp','lock_timeout=2s','statement_timeout=15s']
      AND NOT EXISTS(SELECT 1 FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee<>owner_oid))
    OR (SELECT count(*) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgtype=7 AND t.tgenabled='O'
      AND t.tgfoid='cinatoken_response_observation.reject_no_fetch_overlap_v397()'::regprocedure
      AND t.tgqual IS NULL AND t.tgattr::text='' AND t.tgnargs=0 AND NOT t.tgdeferrable
      AND (t.tgrelid,t.tgname) IN (
        ('cinatoken_response_observation.observations_v392'::regclass,'response_observation_no_fetch_fence_v397'),
        ('cinatoken_gateway.complete_text_no_fetch_resolutions_v370'::regclass,'no_fetch_response_fence_v397'),
        ('cinatoken_gateway.complete_text_platform_terminals_v388'::regclass,'platform_terminal_response_fence_v397')))<>3
  THEN RAISE EXCEPTION 'coinstall v397 postflight differs' USING ERRCODE='P0001'; END IF;
END;
$postflight$;
